// a client appends its claim to the partition its key hashes to, then waits
logs[partitionFor(keyOf(claim), partitions)] += claim
while (claim.requestId !in replies) yield(Unit)

// one processor per partition reads its log in order and decides alone
val d = processor.decide(logs[p][offset++])
replies[d.requestId] = d

// separate steps: two writes, then balance += delta, with no id to recognise a repeat
logs[part(t.from)] += Step(t.requestId, t.from, -t.amount)      // write 1: the debit
logs[part(t.to)] += Step(t.requestId, t.to, t.amount)           // write 2: the credit

// one logged request: the destination drops a credit it has already applied
is Credit -> {
    if (!creditsApplied.add(msg.requestId) && dedupe) return    // seen this credit: drop the duplicate
    balances[msg.wallet] = balances.getValue(msg.wallet) + msg.amount
}

