fun claim(handle: String, userId: String): Boolean {
    val holders = jdbc.queryForList(
        "SELECT user_id FROM handles WHERE name = ?", String::class.java, handle)
    if (holders.isNotEmpty()) return false
    // another server can run the same SELECT right here, and see no row either
    jdbc.update("INSERT INTO handles (name, user_id) VALUES (?, ?)", handle, userId)
    return true
}

