fun claim(handle: String, userId: String): Decision {
    val requestId = UUID.randomUUID().toString()           // kept across retries of this claim
    val record = ProducerRecord("handle-claims", handle, Claim(requestId, userId, handle))
    producer.send(record).get()                             // key = handle: one partition decides
    // a consumer of "handle-decisions" completes one future per request id
    return pending.getOrPut(requestId) { CompletableFuture() }.get(5, TimeUnit.SECONDS)
}
